BEGIN;
UPDATE sites SET water_level='无生产废水（设计）' WHERE site_id='CN0073';
UPDATE sources SET scope='历史验收、既有工艺及监测表；印刷页35-36、41-44截图已核对' WHERE source_id='W01B2S22';
CREATE TABLE water_metrics(metric_id TEXT PRIMARY KEY,site_id TEXT NOT NULL REFERENCES sites,water_id TEXT REFERENCES wastewater,point TEXT NOT NULL,metric TEXT NOT NULL,value_num REAL,value_text TEXT,unit TEXT,result_kind TEXT NOT NULL,statistic TEXT,period TEXT,detection_limit REAL,standard_max REAL,source_id TEXT NOT NULL REFERENCES sources,notes TEXT,CHECK(value_num IS NOT NULL OR value_text IS NOT NULL));
CREATE VIEW v_water_metrics AS SELECT m.*,s.name,s.province,s.city,e.url FROM water_metrics m JOIN sites s USING(site_id) JOIN sources e USING(source_id);
COMMIT;
